/// A way to join online, as JSCalendar's VirtualLocation.
class VirtualPlace {
  const VirtualPlace({
    required this.uri,
    this.name,
    this.description,
    this.features,
  });

  /// Read this payload from a decoded JSON object.
  factory VirtualPlace.fromJson(Map<String, dynamic> json) => VirtualPlace(
        uri: json['uri'] as String,
        name: json['name'] as String?,
        description: json['description'] as String?,
        features: json['features'] == null
            ? null
            : (json['features'] as List<dynamic>)
                .map((e) => VirtualFeature(e as String))
                .toList(),
      );

  /// How to join: an `https` link, or a `tel`, `sip` or `sips` URI for a dial-in. No
  /// other scheme.
  final String uri;
  final String? name;

  /// A passcode, dial-in numbers. Plain text.
  final String? description;
  final List<VirtualFeature>? features;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'uri': uri,
        if (name != null) 'name': name!,
        if (description != null) 'description': description!,
        if (features != null)
          'features': features!.map((e) => e.value).toList(),
      };
}

/// Where the event happens and how to join it (VTI-EVT-060 – 063). Answered by
/// vtc/events/access/show to a registrant who is going, from `revealAt` if set;
/// included in the event itself only where `public` is true.
class AccessDetails {
  const AccessDetails({
    this.places,
    this.virtualPlaces,
    this.notes,
    this.public,
    this.revealAt,
  });

  /// Read this payload from a decoded JSON object.
  factory AccessDetails.fromJson(Map<String, dynamic> json) => AccessDetails(
        places: json['places'] == null
            ? null
            : (json['places'] as List<dynamic>)
                .map((e) => Place.fromJson(e as Map<String, dynamic>))
                .toList(),
        virtualPlaces: json['virtualPlaces'] == null
            ? null
            : (json['virtualPlaces'] as List<dynamic>)
                .map((e) => VirtualPlace.fromJson(e as Map<String, dynamic>))
                .toList(),
        notes: json['notes'] as String?,
        public: json['public'] as bool?,
        revealAt: json['revealAt'] as String?,
      );

  final List<Place>? places;
  final List<VirtualPlace>? virtualPlaces;

  /// Anything else attendees need. Plain text.
  final String? notes;

  /// Show the access details with the event to its whole audience. Absent means false.
  final bool? public;

  /// Not before this, even to a registrant who is going. Absent means on acceptance.
  final EventInstant? revealAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (places != null) 'places': places!.map((e) => e.toJson()).toList(),
        if (virtualPlaces != null)
          'virtualPlaces': virtualPlaces!.map((e) => e.toJson()).toList(),
        if (notes != null) 'notes': notes!,
        if (public != null) 'public': public!,
        if (revealAt != null) 'revealAt': revealAt!,
      };
}

/// A coarse hint shown with the event to its whole audience — `Central London`,
/// `Online` — never the address. Plain text.
typedef PlaceSummary = String;

/// A reminder's offset: how many minutes before the event's start it is due. At most
/// four weeks.
typedef ReminderMinutes = int;

/// Whether a calendar's events take a registrant's check-in without a door challenge,
/// during the event (VTI-EVT-164, 181). `none`: never. `allowed`: taken, but not
/// counted toward attendance. `counting`: taken and counted.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventSelfCheckIn(String value) {
  static const EventSelfCheckIn none = EventSelfCheckIn('none');
  static const EventSelfCheckIn allowed = EventSelfCheckIn('allowed');
  static const EventSelfCheckIn counting = EventSelfCheckIn('counting');

  /// Every value this specification's schema permits.
  static const List<EventSelfCheckIn> values = <EventSelfCheckIn>[
    none,
    allowed,
    counting
  ];
}

/// `archived`: takes no new events; its events are kept.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const CalendarState(String value) {
  static const CalendarState active = CalendarState('active');
  static const CalendarState archived = CalendarState('archived');

  /// Every value this specification's schema permits.
  static const List<CalendarState> values = <CalendarState>[active, archived];
}

/// A calendar: the community's own, or a group's (VTI-EVT-010 – 014). The unit a
/// member follows, and the scope of a host's authority: a group's calendar is run by
/// those who may manage events for that group.
class Calendar {
  const Calendar({
    required this.calendarId,
    required this.name,
    this.description,
    this.color,
    this.groupId,
    this.community,
    this.defaultRoster,
    this.defaultReminderMinutes,
    required this.state,
    required this.createdAt,
    this.selfCheckIn,
    this.countsAttendance,
  });

  /// Read this payload from a decoded JSON object.
  factory Calendar.fromJson(Map<String, dynamic> json) => Calendar(
        calendarId: json['calendarId'] as String,
        name: json['name'] as String,
        description: json['description'] as String?,
        color: json['color'] as String?,
        groupId: json['groupId'] as String?,
        community: json['community'] as bool?,
        defaultRoster: json['defaultRoster'] == null
            ? null
            : RosterSetting(json['defaultRoster'] as String),
        defaultReminderMinutes: json['defaultReminderMinutes'] == null
            ? null
            : (json['defaultReminderMinutes'] as List<dynamic>)
                .map((e) => e as int)
                .toList(),
        state: CalendarState(json['state'] as String),
        createdAt: json['createdAt'] as String,
        selfCheckIn: json['selfCheckIn'] == null
            ? null
            : EventSelfCheckIn(json['selfCheckIn'] as String),
        countsAttendance: json['countsAttendance'] as bool?,
      );

  final CalendarId calendarId;
  final EventTitle name;
  final EventDescription? description;
  final Color? color;

  /// The group whose calendar this is. Absent for the community's own calendar.
  final GroupId? groupId;

  /// True on the community's own calendar, which always exists and cannot be archived
  /// (VTI-EVT-011).
  final bool? community;

  /// The roster setting a new event in this calendar starts with. Absent means `hidden`.
  final RosterSetting? defaultRoster;

  /// The reminders a new event in this calendar suggests, as minutes before its start.
  final List<ReminderMinutes>? defaultReminderMinutes;

  /// `archived`: takes no new events; its events are kept.
  final CalendarState state;
  final EventInstant createdAt;

  /// Absent means `none`.
  final EventSelfCheckIn? selfCheckIn;

  /// Whether its events count toward attendance unless an event says otherwise
  /// (VTI-EVT-180). Absent means true.
  final bool? countsAttendance;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'calendarId': calendarId,
        'name': name,
        if (description != null) 'description': description!,
        if (color != null) 'color': color!,
        if (groupId != null) 'groupId': groupId!,
        if (community != null) 'community': community!,
        if (defaultRoster != null) 'defaultRoster': defaultRoster!.value,
        if (defaultReminderMinutes != null)
          'defaultReminderMinutes': defaultReminderMinutes!,
        'state': state.value,
        'createdAt': createdAt,
        if (selfCheckIn != null) 'selfCheckIn': selfCheckIn!.value,
        if (countsAttendance != null) 'countsAttendance': countsAttendance!,
      };
}

/// Opaque identifier of one directory entry: `dir_` followed by 16 to 64 base64url
/// characters. Random, scoped to one community, and stable for the life of the
/// membership — it survives a rotation of the member's DID, which is why groups, notes
/// and cards are keyed by it. It MUST NOT be derived from, and MUST NOT reveal, any
/// DID of the member, and the same person's entries in two communities MUST NOT share
/// one. Compared by exact string equality.
typedef EntryId = String;

/// How the event invites its audience (VTI-EVT-100). `none`: members find it
/// themselves. `notify`: the community invites each member of the audience, on
/// publication and as members come into it. `expect`: as `notify`, and a reply is
/// expected — hosts see who has not answered. An invitation never registers anyone.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventInviteMode(String value) {
  static const EventInviteMode none = EventInviteMode('none');
  static const EventInviteMode notify = EventInviteMode('notify');
  static const EventInviteMode expect = EventInviteMode('expect');

  /// Every value this specification's schema permits.
  static const List<EventInviteMode> values = <EventInviteMode>[
    none,
    notify,
    expect
  ];
}

/// The event's own identifier (VTI-EVT-140 – 145): minted by the community's VTA from
/// a `vtc-event` template, authorized by a revocable community credential, and used
/// only to sign the event's tickets and attendance records.
class EventIdentity {
  const EventIdentity({
    required this.did,
    this.authorityValidUntil,
  });

  /// Read this payload from a decoded JSON object.
  factory EventIdentity.fromJson(Map<String, dynamic> json) => EventIdentity(
        did: json['did'] as String,
        authorityValidUntil: json['authorityValidUntil'] as String?,
      );

  /// The event's identifier.
  final String did;

  /// When the community's authorization credential to it expires; renewed while the
  /// event stands. Hosts only.
  final EventInstant? authorityValidUntil;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'did': did,
        if (authorityValidUntil != null)
          'authorityValidUntil': authorityValidUntil!,
      };
}

/// Whether the event admits guests — parties who are not members of the community
/// (VTI-EVT-150, 151). `none`: no guests. `invited`: a guest an invitation names, or
/// who redeemed a link made for guests. `open`: any party that signs its own request.
/// The audience never admits a guest.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventGuestAdmission(String value) {
  static const EventGuestAdmission none = EventGuestAdmission('none');
  static const EventGuestAdmission invited = EventGuestAdmission('invited');
  static const EventGuestAdmission open = EventGuestAdmission('open');

  /// Every value this specification's schema permits.
  static const List<EventGuestAdmission> values = <EventGuestAdmission>[
    none,
    invited,
    open
  ];
}

/// Opaque identifier of a badge: `bdg_` followed by 16 to 64 base64url characters.
/// Random, community-scoped, never reused (VTI-BDG-001).
typedef BadgeId = String;

/// An event as the caller may see it. Members a caller may not see are left out:
/// `registration` settings' `questions` are shown to everyone who may register,
/// `access` only where it is public, `goingCount` as the roster setting allows
/// (VTI-EVT-054).
class Event {
  const Event({
    required this.eventId,
    required this.calendarId,
    required this.kind,
    required this.status,
    required this.title,
    this.description,
    required this.when,
    this.placeSummary,
    this.access,
    required this.audience,
    required this.registration,
    required this.roster,
    this.showCount,
    this.countThreshold,
    required this.listed,
    this.accessibility,
    this.suggestedReminderMinutes,
    this.hosts,
    this.goingCount,
    this.full,
    required this.sequence,
    this.cancelReason,
    this.publishedAt,
    this.cancelledAt,
    required this.createdAt,
    required this.updatedAt,
    this.invite,
    this.membersMayInvite,
    this.identity,
    this.guests,
    this.tickets,
    this.countsAttendance,
    this.attendanceBadge,
  });

  /// Read this payload from a decoded JSON object.
  factory Event.fromJson(Map<String, dynamic> json) => Event(
        eventId: json['eventId'] as String,
        calendarId: json['calendarId'] as String,
        kind: EventKind(json['kind'] as String),
        status: EventLifecycle(json['status'] as String),
        title: json['title'] as String,
        description: json['description'] as String?,
        when: When.fromJson(json['when'] as Map<String, dynamic>),
        placeSummary: json['placeSummary'] as String?,
        access: json['access'] == null
            ? null
            : AccessDetails.fromJson(json['access'] as Map<String, dynamic>),
        audience:
            EventAudience.fromJson(json['audience'] as Map<String, dynamic>),
        registration: RegistrationSettings.fromJson(
            json['registration'] as Map<String, dynamic>),
        roster: RosterSetting(json['roster'] as String),
        showCount: json['showCount'] as bool?,
        countThreshold: json['countThreshold'] as int?,
        listed: json['listed'] as bool,
        accessibility: json['accessibility'] == null
            ? null
            : Accessibility.fromJson(
                json['accessibility'] as Map<String, dynamic>),
        suggestedReminderMinutes: json['suggestedReminderMinutes'] == null
            ? null
            : (json['suggestedReminderMinutes'] as List<dynamic>)
                .map((e) => e as int)
                .toList(),
        hosts: json['hosts'] == null
            ? null
            : (json['hosts'] as List<dynamic>).map((e) => e as String).toList(),
        goingCount: json['goingCount'] == null
            ? null
            : Count.fromJson(json['goingCount'] as Map<String, dynamic>),
        full: json['full'] as bool?,
        sequence: json['sequence'] as int,
        cancelReason: json['cancelReason'] as String?,
        publishedAt: json['publishedAt'] as String?,
        cancelledAt: json['cancelledAt'] as String?,
        createdAt: json['createdAt'] as String,
        updatedAt: json['updatedAt'] as String,
        invite: json['invite'] == null
            ? null
            : EventInviteMode(json['invite'] as String),
        membersMayInvite: json['membersMayInvite'] as bool?,
        identity: json['identity'] == null
            ? null
            : EventIdentity.fromJson(json['identity'] as Map<String, dynamic>),
        guests: json['guests'] == null
            ? null
            : EventGuestAdmission(json['guests'] as String),
        tickets: json['tickets'] as bool?,
        countsAttendance: json['countsAttendance'] as bool?,
        attendanceBadge: json['attendanceBadge'] as String?,
      );

  final EventId eventId;
  final CalendarId calendarId;
  final EventKind kind;
  final EventLifecycle status;
  final EventTitle title;
  final EventDescription? description;
  final When when;
  final PlaceSummary? placeSummary;

  /// Only where the access details are public, or the caller is a host.
  final AccessDetails? access;
  final EventAudience audience;
  final RegistrationSettings registration;
  final RosterSetting roster;

  /// Show the number going to the audience, subject to `countThreshold`. Absent means
  /// false.
  final bool? showCount;

  /// Below this many going, a count is shown as `fewerThan`. Absent means 5.
  final int? countThreshold;

  /// Listed to its whole audience. An unlisted event is answered by vtc/events/show to a
  /// member of its audience who names it, and left out of vtc/events/list (VTI-EVT-022).
  final bool listed;
  final Accessibility? accessibility;

  /// Reminders the hosts suggest, as minutes before the start. A member's agent applies
  /// them unless the member chose otherwise; the community sends no reminder itself
  /// (VTI-EVT-040).
  final List<ReminderMinutes>? suggestedReminderMinutes;

  /// The event's appointed hosts. Its creator is the first.
  final List<EntryId>? hosts;

  /// People going, plus-ones included: exact for a host; for anyone else only where
  /// `showCount` is true, and then as `Count` states.
  final Count? goingCount;

  /// True when `capacity` is reached. Shown to everyone who may register, whatever
  /// `showCount` says, since a registrant learns it anyway.
  final bool? full;

  /// Incremented on every change of `when`, `access`, `status` or `kind` after
  /// publication — the changes a registrant must notice, as iTIP's SEQUENCE
  /// (VTI-EVT-006).
  final int sequence;

  /// Present once cancelled, where the host gave one. Plain text.
  final String? cancelReason;
  final EventInstant? publishedAt;
  final EventInstant? cancelledAt;
  final EventInstant createdAt;
  final EventInstant updatedAt;

  /// Absent means `none`.
  final EventInviteMode? invite;

  /// Members of the audience may invite other members of it, within the community's
  /// daily limit (VTI-EVT-105). Absent means false.
  final bool? membersMayInvite;

  /// Present where the event has its own identifier (VTI-EVT-140).
  final EventIdentity? identity;

  /// Absent means `none` (VTI-EVT-150).
  final EventGuestAdmission? guests;

  /// Whether registrants going are issued a ticket (VTI-EVT-170). Absent means false.
  final bool? tickets;

  /// Whether the event counts toward attendance (VTI-EVT-180). Absent: its calendar's
  /// default.
  final bool? countsAttendance;

  /// A badge offered to a member when their check-in is recorded, for them to accept
  /// (VTI-EVT-186).
  final BadgeId? attendanceBadge;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'eventId': eventId,
        'calendarId': calendarId,
        'kind': kind.value,
        'status': status.value,
        'title': title,
        if (description != null) 'description': description!,
        'when': when.toJson(),
        if (placeSummary != null) 'placeSummary': placeSummary!,
        if (access != null) 'access': access!.toJson(),
        'audience': audience.toJson(),
        'registration': registration.toJson(),
        'roster': roster.value,
        if (showCount != null) 'showCount': showCount!,
        if (countThreshold != null) 'countThreshold': countThreshold!,
        'listed': listed,
        if (accessibility != null) 'accessibility': accessibility!.toJson(),
        if (suggestedReminderMinutes != null)
          'suggestedReminderMinutes': suggestedReminderMinutes!,
        if (hosts != null) 'hosts': hosts!,
        if (goingCount != null) 'goingCount': goingCount!.toJson(),
        if (full != null) 'full': full!,
        'sequence': sequence,
        if (cancelReason != null) 'cancelReason': cancelReason!,
        if (publishedAt != null) 'publishedAt': publishedAt!,
        if (cancelledAt != null) 'cancelledAt': cancelledAt!,
        'createdAt': createdAt,
        'updatedAt': updatedAt,
        if (invite != null) 'invite': invite!.value,
        if (membersMayInvite != null) 'membersMayInvite': membersMayInvite!,
        if (identity != null) 'identity': identity!.toJson(),
        if (guests != null) 'guests': guests!.value,
        if (tickets != null) 'tickets': tickets!,
        if (countsAttendance != null) 'countsAttendance': countsAttendance!,
        if (attendanceBadge != null) 'attendanceBadge': attendanceBadge!,
      };
}

/// Where a registration stands (VTI-EVT-032). `going`: has a place. `maybe`: has said
/// maybe; holds no place. `pending`: awaits a host's decision. `waitlisted`: waits for
/// a place, in order. `withdrawn`: the registrant withdrew. `declined`: a host
/// declined a pending registration. `removed`: a host removed it.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const RegistrationStatus(String value) {
  static const RegistrationStatus going = RegistrationStatus('going');
  static const RegistrationStatus maybe = RegistrationStatus('maybe');
  static const RegistrationStatus pending = RegistrationStatus('pending');
  static const RegistrationStatus waitlisted = RegistrationStatus('waitlisted');
  static const RegistrationStatus withdrawn = RegistrationStatus('withdrawn');
  static const RegistrationStatus declined = RegistrationStatus('declined');
  static const RegistrationStatus removed = RegistrationStatus('removed');

  /// Every value this specification's schema permits.
  static const List<RegistrationStatus> values = <RegistrationStatus>[
    going,
    maybe,
    pending,
    waitlisted,
    withdrawn,
    declined,
    removed
  ];
}

/// One registrant's registration for one event. The registrant reads all of it; a host
/// reads all of it; another registrant on a `visible` roster reads only `entryId`,
/// `status` and `guests` (VTI-EVT-053). Exactly one of `entryId` (a member) and
/// `registrantDid` (a partner's member, VTI-EVT-134) names the registrant.
class Registration {
  const Registration({
    required this.registrationId,
    required this.eventId,
    this.entryId,
    this.registrantDid,
    required this.status,
    required this.guests,
    this.answers,
    this.codeOfConductAcknowledged,
    this.waitlistPosition,
    required this.roster,
    required this.eventSequence,
    this.note,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory Registration.fromJson(Map<String, dynamic> json) => Registration(
        registrationId: json['registrationId'] as String,
        eventId: json['eventId'] as String,
        entryId: json['entryId'] as String?,
        registrantDid: json['registrantDid'] as String?,
        status: RegistrationStatus(json['status'] as String),
        guests: json['guests'] as int,
        answers: json['answers'] == null
            ? null
            : (json['answers'] as Map<String, dynamic>)
                .map((k, v) => MapEntry(k, v)),
        codeOfConductAcknowledged: json['codeOfConductAcknowledged'] as String?,
        waitlistPosition: json['waitlistPosition'] as int?,
        roster: RosterSetting(json['roster'] as String),
        eventSequence: json['eventSequence'] as int,
        note: json['note'] as String?,
        createdAt: json['createdAt'] as String,
        updatedAt: json['updatedAt'] as String,
      );

  final RegistrationId registrationId;
  final EventId eventId;

  /// The registrant's directory entry, where they are a member. Exactly one of `entryId`
  /// and `registrantDid` is present.
  final EntryId? entryId;

  /// A registrant who is not a member of the community — a partner's member
  /// (VTI-EVT-134) — by the DID they presented as. Shown to the event's hosts and to the
  /// registrant only.
  final String? registrantDid;
  final RegistrationStatus status;

  /// Plus-ones the registrant brings.
  final int guests;

  /// The registrant's and the hosts' view only.
  final RegistrationAnswers? answers;

  /// The `sha256` of the code of conduct the registrant acknowledged.
  final String? codeOfConductAcknowledged;

  /// While `waitlisted`: the registrant's place in the queue, 1 first.
  final int? waitlistPosition;

  /// The roster setting the registration was made under (VTI-EVT-052).
  final RosterSetting roster;

  /// The event's `sequence` when the registration last changed, so a registrant sees
  /// whether the event changed since.
  final int eventSequence;

  /// A host's note on a decline or removal, shown to the registrant. Plain text.
  final String? note;
  final EventInstant createdAt;
  final EventInstant updatedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'registrationId': registrationId,
        'eventId': eventId,
        if (entryId != null) 'entryId': entryId!,
        if (registrantDid != null) 'registrantDid': registrantDid!,
        'status': status.value,
        'guests': guests,
        if (answers != null) 'answers': answers!,
        if (codeOfConductAcknowledged != null)
          'codeOfConductAcknowledged': codeOfConductAcknowledged!,
        if (waitlistPosition != null) 'waitlistPosition': waitlistPosition!,
        'roster': roster.value,
        'eventSequence': eventSequence,
        if (note != null) 'note': note!,
        'createdAt': createdAt,
        'updatedAt': updatedAt,
      };
}

/// What a receipt says of the event a registration belongs to: enough for the
/// registrant's agent to show it as it was when the community answered (VTI-EVT-092).
class EventRef {
  const EventRef({
    required this.eventId,
    required this.title,
    required this.when,
    required this.status,
    required this.sequence,
    this.suggestedReminderMinutes,
    this.placeSummary,
  });

  /// Read this payload from a decoded JSON object.
  factory EventRef.fromJson(Map<String, dynamic> json) => EventRef(
        eventId: json['eventId'] as String,
        title: json['title'] as String,
        when: When.fromJson(json['when'] as Map<String, dynamic>),
        status: EventLifecycle(json['status'] as String),
        sequence: json['sequence'] as int,
        suggestedReminderMinutes: json['suggestedReminderMinutes'] == null
            ? null
            : (json['suggestedReminderMinutes'] as List<dynamic>)
                .map((e) => e as int)
                .toList(),
        placeSummary: json['placeSummary'] as String?,
      );

  final EventId eventId;
  final EventTitle title;
  final When when;
  final EventLifecycle status;
  final int sequence;

  /// The reminders the event's hosts suggest, as minutes before its start, so the
  /// registrant's agent can fire them without reading the event again (VTI-CAL-041).
  /// Absent where the hosts suggest none.
  final List<ReminderMinutes>? suggestedReminderMinutes;

  /// The event's coarse place hint, never an address (VTI-EVT-062). Absent where the
  /// event has none.
  final PlaceSummary? placeSummary;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'eventId': eventId,
        'title': title,
        'when': when.toJson(),
        'status': status.value,
        'sequence': sequence,
        if (suggestedReminderMinutes != null)
          'suggestedReminderMinutes': suggestedReminderMinutes!,
        if (placeSummary != null) 'placeSummary': placeSummary!,
      };
}

/// Opaque identifier of one invitation to one event: `inv_` followed by 16 to 64
/// base64url characters.
typedef EventInvitationId = String;

/// Who invited (VTI-EVT-106). `audience`: the community, under the event's invitation
/// mode (VTI-EVT-101). `host`: a host, by name (VTI-EVT-103). `member`: a member of
/// the audience (VTI-EVT-105). `link`: the invitee redeemed an invitation link
/// (VTI-EVT-107).
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventInviter(String value) {
  static const EventInviter audience = EventInviter('audience');
  static const EventInviter host = EventInviter('host');
  static const EventInviter member = EventInviter('member');
  static const EventInviter link = EventInviter('link');

  /// Every value this specification's schema permits.
  static const List<EventInviter> values = <EventInviter>[
    audience,
    host,
    member,
    link
  ];
}

/// The invitee's answer (VTI-EVT-104). `none`: not answered. `going`, `maybe`:
/// answered by registering. `declined`: the invitee said they will not come — recorded
/// here and nowhere else; not a host's decline of a registration.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventInvitationAnswer(String value) {
  static const EventInvitationAnswer none = EventInvitationAnswer('none');
  static const EventInvitationAnswer going = EventInvitationAnswer('going');
  static const EventInvitationAnswer maybe = EventInvitationAnswer('maybe');
  static const EventInvitationAnswer declined =
      EventInvitationAnswer('declined');

  /// Every value this specification's schema permits.
  static const List<EventInvitationAnswer> values = <EventInvitationAnswer>[
    none,
    going,
    maybe,
    declined
  ];
}

/// One member's invitation to one event (VTI-EVT-102). Seen by the event's hosts and
/// by the invitee; never by anyone else (VTI-EVT-106).
class EventInvitation {
  const EventInvitation({
    required this.invitationId,
    required this.eventId,
    required this.entryId,
    required this.invitedBy,
    this.inviterEntryId,
    required this.replyExpected,
    required this.answer,
    this.answeredAt,
    this.revoked,
    required this.createdAt,
  });

  /// Read this payload from a decoded JSON object.
  factory EventInvitation.fromJson(Map<String, dynamic> json) =>
      EventInvitation(
        invitationId: json['invitationId'] as String,
        eventId: json['eventId'] as String,
        entryId: json['entryId'] as String,
        invitedBy: EventInviter(json['invitedBy'] as String),
        inviterEntryId: json['inviterEntryId'] as String?,
        replyExpected: json['replyExpected'] as bool,
        answer: EventInvitationAnswer(json['answer'] as String),
        answeredAt: json['answeredAt'] as String?,
        revoked: json['revoked'] as bool?,
        createdAt: json['createdAt'] as String,
      );

  final EventInvitationId invitationId;
  final EventId eventId;

  /// The invitee.
  final EntryId entryId;
  final EventInviter invitedBy;

  /// The host or member who invited, where `invitedBy` is `host` or `member`. Shown to
  /// hosts only.
  final EntryId? inviterEntryId;

  /// The event was `expect` when the invitation was made (VTI-EVT-100).
  final bool replyExpected;
  final EventInvitationAnswer answer;
  final EventInstant? answeredAt;

  /// A host revoked it (VTI-EVT-103); its notification was withdrawn. Absent means
  /// false.
  final bool? revoked;
  final EventInstant createdAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'invitationId': invitationId,
        'eventId': eventId,
        'entryId': entryId,
        'invitedBy': invitedBy.value,
        if (inviterEntryId != null) 'inviterEntryId': inviterEntryId!,
        'replyExpected': replyExpected,
        'answer': answer.value,
        if (answeredAt != null) 'answeredAt': answeredAt!,
        if (revoked != null) 'revoked': revoked!,
        'createdAt': createdAt,
      };
}

/// Opaque identifier of one invitation link: `lnk_` followed by 16 to 64 base64url
/// characters. Not the code: the code is shown once, at creation, and kept only as a
/// digest (VTI-EVT-107).
typedef EventInvitationLinkId = String;

/// An invitation link as its hosts see it, never with its code (VTI-EVT-107).
class EventInvitationLink {
  const EventInvitationLink({
    required this.linkId,
    required this.eventId,
    this.label,
    required this.maxRedemptions,
    required this.redemptions,
    required this.expiresAt,
    this.revokedAt,
    required this.createdAt,
    this.forGuests,
  });

  /// Read this payload from a decoded JSON object.
  factory EventInvitationLink.fromJson(Map<String, dynamic> json) =>
      EventInvitationLink(
        linkId: json['linkId'] as String,
        eventId: json['eventId'] as String,
        label: json['label'] as String?,
        maxRedemptions: json['maxRedemptions'] as int,
        redemptions: json['redemptions'] as int,
        expiresAt: json['expiresAt'] as String,
        revokedAt: json['revokedAt'] as String?,
        createdAt: json['createdAt'] as String,
        forGuests: json['forGuests'] as bool?,
      );

  final EventInvitationLinkId linkId;
  final EventId eventId;

  /// What the hosts call it — `Flyer at the library`. Plain text.
  final String? label;

  /// The most members who may redeem it.
  final int maxRedemptions;

  /// How many have.
  final int redemptions;
  final EventInstant expiresAt;
  final EventInstant? revokedAt;
  final EventInstant createdAt;

  /// A link for guests — parties who are not members — under the event's `invited` guest
  /// setting (VTI-EVT-151). Absent means false: a link for members.
  final bool? forGuests;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'linkId': linkId,
        'eventId': eventId,
        if (label != null) 'label': label!,
        'maxRedemptions': maxRedemptions,
        'redemptions': redemptions,
        'expiresAt': expiresAt,
        if (revokedAt != null) 'revokedAt': revokedAt!,
        'createdAt': createdAt,
        if (forGuests != null) 'forGuests': forGuests!,
      };
}

/// What an opt-out covers (VTI-EVT-110): invitations to one `event`, or from one
/// `calendar`.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventOptOutScope(String value) {
  static const EventOptOutScope event = EventOptOutScope('event');
  static const EventOptOutScope calendar = EventOptOutScope('calendar');

  /// Every value this specification's schema permits.
  static const List<EventOptOutScope> values = <EventOptOutScope>[
    event,
    calendar
  ];
}

/// A member's opt-out of invitations (VTI-EVT-110). It removes them from no audience
/// and stops no host's invitation by name.
class EventOptOut {
  const EventOptOut({
    required this.scope,
    this.eventId,
    this.calendarId,
    required this.createdAt,
  });

  /// Read this payload from a decoded JSON object.
  factory EventOptOut.fromJson(Map<String, dynamic> json) => EventOptOut(
        scope: EventOptOutScope(json['scope'] as String),
        eventId: json['eventId'] as String?,
        calendarId: json['calendarId'] as String?,
        createdAt: json['createdAt'] as String,
      );

  final EventOptOutScope scope;

  /// Present exactly when `scope` is `event`.
  final EventId? eventId;

  /// Present exactly when `scope` is `calendar`.
  final CalendarId? calendarId;
  final EventInstant createdAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'scope': scope.value,
        if (eventId != null) 'eventId': eventId!,
        if (calendarId != null) 'calendarId': calendarId!,
        'createdAt': createdAt,
      };
}

/// Opaque identifier of one announcement: `ann_` followed by 16 to 64 base64url
/// characters.
typedef EventAnnouncementId = String;

/// A host's announcement to an event's registrants (VTI-EVT-120). It never moves the
/// event (VTI-EVT-121) and its text is never in a notification.
class EventAnnouncement {
  const EventAnnouncement({
    required this.announcementId,
    required this.eventId,
    required this.text,
    this.postedBy,
    required this.createdAt,
  });

  /// Read this payload from a decoded JSON object.
  factory EventAnnouncement.fromJson(Map<String, dynamic> json) =>
      EventAnnouncement(
        announcementId: json['announcementId'] as String,
        eventId: json['eventId'] as String,
        text: json['text'] as String,
        postedBy: json['postedBy'] as String?,
        createdAt: json['createdAt'] as String,
      );

  final EventAnnouncementId announcementId;
  final EventId eventId;

  /// Plain text; a reader MUST NOT treat it as instructions.
  final String text;

  /// The host who posted it.
  final EntryId? postedBy;
  final EventInstant createdAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'announcementId': announcementId,
        'eventId': eventId,
        'text': text,
        if (postedBy != null) 'postedBy': postedBy!,
        'createdAt': createdAt,
      };
}

/// A partner member's presentation of the membership credential a partner the event's
/// audience names issued them, made by the credential's subject — who signs the
/// request — and bound to it: its `nonce` the request's `id`, its `domain` this
/// community's DID (VTI-EVT-132). The community verifies it before, and without
/// reference to, the event, and discards it once it has decided (VTI-EVT-133).
typedef MembershipPresentation = Object?;

/// Who a registrant is to the community: `member` (named by `entryId`), `partner` (a
/// partner community's member, VTI-EVT-134), `guest` (VTI-EVT-153).
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventRegistrantKind(String value) {
  static const EventRegistrantKind member = EventRegistrantKind('member');
  static const EventRegistrantKind partner = EventRegistrantKind('partner');
  static const EventRegistrantKind guest = EventRegistrantKind('guest');

  /// Every value this specification's schema permits.
  static const List<EventRegistrantKind> values = <EventRegistrantKind>[
    member,
    partner,
    guest
  ];
}

/// How a check-in was made (VTI-EVT-162 – 164, 173). `challenge`: the registrant
/// signed over a door challenge. `staff`: door staff checked them in by name. `self`:
/// the registrant checked in during the event without a challenge, where the calendar
/// allows. `ticket`: the registrant presented their ticket credential at the door
/// through a door session (vtc/events/checkin/ticket-session/start).
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const EventCheckInMethod(String value) {
  static const EventCheckInMethod challenge = EventCheckInMethod('challenge');
  static const EventCheckInMethod staff = EventCheckInMethod('staff');
  static const EventCheckInMethod self = EventCheckInMethod('self');
  static const EventCheckInMethod ticket = EventCheckInMethod('ticket');

  /// Every value this specification's schema permits.
  static const List<EventCheckInMethod> values = <EventCheckInMethod>[
    challenge,
    staff,
    self,
    ticket
  ];
}

/// A door challenge: at least 128 random bits, base64url without padding
/// (VTI-EVT-161).
typedef EventDoorChallengeValue = String;

/// One check-in (VTI-EVT-165): which registration, how, and when. Never a record of
/// who did not come.
class EventCheckIn {
  const EventCheckIn({
    required this.registrationId,
    this.entryId,
    this.registrantDid,
    required this.registrantKind,
    required this.method,
    required this.checkedInAt,
    this.checkedInBy,
    this.counts,
  });

  /// Read this payload from a decoded JSON object.
  factory EventCheckIn.fromJson(Map<String, dynamic> json) => EventCheckIn(
        registrationId: json['registrationId'] as String,
        entryId: json['entryId'] as String?,
        registrantDid: json['registrantDid'] as String?,
        registrantKind: EventRegistrantKind(json['registrantKind'] as String),
        method: EventCheckInMethod(json['method'] as String),
        checkedInAt: json['checkedInAt'] as String,
        checkedInBy: json['checkedInBy'] as String?,
        counts: json['counts'] as bool?,
      );

  final RegistrationId registrationId;

  /// Present for a member.
  final EntryId? entryId;

  /// Present for a partner's member or a guest.
  final String? registrantDid;
  final EventRegistrantKind registrantKind;
  final EventCheckInMethod method;
  final EventInstant checkedInAt;

  /// For `staff`: the door staff member who recorded it.
  final EntryId? checkedInBy;

  /// Whether it counts toward the registrant's attendance (VTI-EVT-180 – 183).
  final bool? counts;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'registrationId': registrationId,
        if (entryId != null) 'entryId': entryId!,
        if (registrantDid != null) 'registrantDid': registrantDid!,
        'registrantKind': registrantKind.value,
        'method': method.value,
        'checkedInAt': checkedInAt,
        if (checkedInBy != null) 'checkedInBy': checkedInBy!,
        if (counts != null) 'counts': counts!,
      };
}

/// How many counting events a member attended in one calendar in one month
/// (VTI-EVT-185): the record attendance is counted from.
class EventAttendanceTally {
  const EventAttendanceTally({
    required this.calendarId,
    required this.month,
    required this.count,
  });

  /// Read this payload from a decoded JSON object.
  factory EventAttendanceTally.fromJson(Map<String, dynamic> json) =>
      EventAttendanceTally(
        calendarId: json['calendarId'] as String,
        month: json['month'] as String,
        count: json['count'] as int,
      );

  final CalendarId calendarId;

  /// `YYYY-MM`, in UTC.
  final String month;
  final int count;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'calendarId': calendarId,
        'month': month,
        'count': count,
      };
}
